package theme

import (
	"fmt"
	"strconv"
	"strings"
)

// header starts each generated file.
const header = "Code generated by go generate ./internal/theme; DO NOT EDIT."

// CSS returns the web UI's color variables: light by default, dark when
// the OS prefers it, and either one forced by data-theme on the root.
func CSS() string {
	var b strings.Builder
	fmt.Fprintf(&b, "/* %s */\n\n", header)
	block := func(selector string, dark bool, indent string) {
		fmt.Fprintf(&b, "%s%s {\n", indent, selector)
		for _, c := range Palette() {
			fmt.Fprintf(&b, "%s  --%s: %s;\n", indent, c.Name, pick(c.Dark, c.Light, dark))
		}
		for _, s := range States() {
			fmt.Fprintf(&b, "%s  --%s: %s;\n", indent, s.Name, pick(s.Dark, s.Light, dark))
		}
		scheme := "light"
		if dark {
			scheme = "dark"
		}
		fmt.Fprintf(&b, "%s  color-scheme: %s;\n%s}\n", indent, scheme, indent)
	}
	block(":root", false, "")
	b.WriteString("\n@media (prefers-color-scheme: dark) {\n")
	block(`:root:not([data-theme="light"])`, true, "  ")
	b.WriteString("}\n\n")
	block(`:root[data-theme="dark"]`, true, "")
	return b.String()
}

func pick(dark, light string, isDark bool) string {
	if isDark {
		return dark
	}
	return light
}

// TS returns the states' words and glyphs as a TypeScript module.
func TS() string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n\n", header)
	b.WriteString("export const states = {\n")
	for _, s := range States() {
		fmt.Fprintf(&b, "  %s: { word: %s, glyph: %s, ascii: %s },\n", s.Name, strconv.Quote(s.Word), strconv.Quote(s.Glyph), strconv.Quote(s.ASCII))
	}
	b.WriteString("} as const;\n\nexport type StateName = keyof typeof states;\n")
	return b.String()
}
